    fun scheme(seed: Color, dark: Boolean): ColorScheme? {
        val v = rows[seed.toArgb()]?.get(if (dark) 1 else 0) ?: return null
        val defaults = if (dark) darkColorScheme() else lightColorScheme()
        return defaults.copy(
            primary = v[0], onPrimary = v[1], primaryContainer = v[2], onPrimaryContainer = v[3],
            secondary = v[4], onSecondary = v[5], secondaryContainer = v[6], onSecondaryContainer = v[7],
            tertiary = v[8], onTertiary = v[9], tertiaryContainer = v[10], onTertiaryContainer = v[11],
            error = v[12], errorContainer = v[13], onError = v[14], onErrorContainer = v[15],
            background = v[16], onBackground = v[17], surface = v[18], onSurface = v[19],
            surfaceVariant = v[20], onSurfaceVariant = v[21], outline = v[22],
            inverseOnSurface = v[23], inverseSurface = v[24], inversePrimary = v[25],
            surfaceTint = v[26], outlineVariant = v[27], surfaceContainerLowest = v[28],
            surfaceContainerLow = v[29], surfaceContainer = v[30], surfaceContainerHigh = v[31],
            surfaceContainerHighest = v[32], scrim = v[33],
        )
    }

    fun seed(seed: Color, dark: Boolean): Color = rows[seed.toArgb()]?.get(if (dark) 1 else 0)?.first() ?: seed
